<?php
declare(strict_types=1);
namespace Modules\Auxiliary;
/** Selective market closure import. Never imports jobs, request control or server history. */
final class CapturedMarket {
 public const PINS=['rootpackage-manifest.json'=>'186950adfb29ebdb45a1b1c373dae3c1070eb8d808f56d4e8e9fb823e48d6e87','phase3/final-data-manifest.json'=>'bd618297dbc080c2ed9db1df512dec122501bc4de15e27968838f3974769b741','phase3/local-verification-report.json'=>'9e4269f61c49af7828cb2a10095c9f54ada9df715ebd1f0bddddbee2cc0d4515'];
 private static function file(string $root,string $relative,int $max):string {if(!preg_match('~^[a-zA-Z0-9_./-]+$~D',$relative)||str_contains($relative,'..'))throw new \RuntimeException('MARKET_CAPTURE_PATH_INVALID');$path=$root.'/'.$relative;$real=realpath($path);$prefix=str_replace('\\','/',$root).'/';if(!$real||!str_starts_with(str_replace('\\','/',$real),$prefix)||is_link($path)||!is_file($path)||filesize($path)>$max)throw new \RuntimeException('MARKET_CAPTURE_FILE_INVALID');return file_get_contents($path);}
 public static function plan(string $directory):array {$root=realpath($directory);if(!$root||is_link($directory))throw new \RuntimeException('MARKET_CAPTURE_ROOT_INVALID');$meta=[];foreach(self::PINS as $relative=>$sha){$raw=self::file($root,$relative,8388608);if(!hash_equals($sha,hash('sha256',$raw)))throw new \RuntimeException('MARKET_CAPTURE_METADATA_HASH');$meta[$relative]=json_decode($raw,true,512,JSON_THROW_ON_ERROR);}if(($meta['rootpackage-manifest.json']['projectId']??null)!=='f6e21e3c-d974-4604-82fb-333da66559d2')throw new \RuntimeException('MARKET_CAPTURE_PROJECT');$index=[];foreach($meta['phase3/final-data-manifest.json']['files']??[]as $file){$path=$file['path']??'';if(isset($index[$path]))throw new \RuntimeException('MARKET_CAPTURE_DUPLICATE_PATH');$index[$path]=$file;}$closures=[];
 foreach($index as $path=>$entry){if(!preg_match('~^(market/results/[a-zA-Z0-9_-]{1,80}/[0-9]{8}T[0-9]{6}Z-[a-f0-9]+/)(COMPLETE)$~D',$path,$match))continue;$prefix=$match[1];$files=[];foreach(['COMPLETE'=>4096,'snapshot.json'=>16000000,'records.csv'=>16000000,'sources.csv'=>1000000]as $name=>$limit){$e=$index[$prefix.$name]??throw new \RuntimeException('MARKET_CAPTURE_CLOSURE_MISSING');if(($e['localBytesRetained']??false)!==true)throw new \RuntimeException('MARKET_CAPTURE_BYTES_WITHHELD');$raw=self::file($root,'phase3/captured/'.$prefix.$name,$limit);if(strlen($raw)!==($e['bytes']??-1)||!hash_equals((string)($e['sha256']??''),hash('sha256',$raw)))throw new \RuntimeException('MARKET_CAPTURE_PAYLOAD_HASH');$files[$name]=$raw;}$complete=json_decode($files['COMPLETE'],true,512,JSON_THROW_ON_ERROR);$names=array_keys($complete);sort($names);if($names!==['records.csv','snapshot.json','sources.csv'])throw new \RuntimeException('MARKET_CAPTURE_MANIFEST_SHAPE');foreach($complete as $name=>$sha)if(!is_string($sha)||!hash_equals($sha,hash('sha256',$files[$name])))throw new \RuntimeException('MARKET_CAPTURE_COMPLETE_HASH');$snapshot=\Modules\Rental\Importer::decodeExact($files['snapshot.json']);Market::validate($snapshot);$sha=hash('sha256',$files['snapshot.json']);if(isset($closures[$snapshot['run_id']]))throw new \RuntimeException('MARKET_CAPTURE_DUPLICATE_RUN');$closures[$snapshot['run_id']]=['relative'=>$prefix,'snapshot_sha256'=>$sha,'records'=>count($snapshot['records']),'files'=>$files];}
 if(count($closures)!==15)throw new \RuntimeException('MARKET_CAPTURE_EXPECTED15_CLOSURES');ksort($closures);return $closures;}
 public static function import(string $root):array {$plan=self::plan($root);$results=[];foreach($plan as $key=>$closure){$dir=APP_ROOT.'/private/market-capture/'.$closure['snapshot_sha256'];if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new \RuntimeException('MARKET_CAPTURE_PRIVATE_STORE');$hashes=[];foreach($closure['files']as $name=>$raw){$target=$dir.'/'.$name;$hashes[$name]=hash('sha256',$raw);if(is_file($target)){if(is_link($target)||!hash_equals($hashes[$name],hash_file('sha256',$target)))throw new \RuntimeException('MARKET_CAPTURE_IMMUTABLE_CONFLICT');}else{$h=fopen($target,'xb');if(!$h||fwrite($h,$raw)!==strlen($raw))throw new \RuntimeException('MARKET_CAPTURE_COPY_FAILED');fclose($h);@chmod($target,0400);}}$receipt=['source_pins'=>self::PINS,'source_relative'=>$closure['relative'],'run_key'=>$key,'files'=>$hashes,'business_scope'=>'market closure only; no jobs/control/journal activation'];$receiptRaw=json_encode($receipt,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR);$target=$dir.'/source-receipt.json';if(is_file($target)&&file_get_contents($target)!==$receiptRaw)throw new \RuntimeException('MARKET_CAPTURE_RECEIPT_CONFLICT');if(!is_file($target)){file_put_contents($target,$receiptRaw,LOCK_EX);@chmod($target,0400);}$results[$key]=Market::importDirectory($dir);}$report=['closures'=>count($results),'records'=>array_sum(array_column($results,'records')),'runs'=>$results,'source_pins'=>self::PINS,'global_restore_ready'=>false];file_put_contents(APP_ROOT.'/private/market-capture/import-receipt.json',json_encode($report,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));return $report;}
}
